package("pugixml")
    set_homepage("https://pugixml.org")
    set_license("MIT")
    set_urls("$(projectdir)/third_party/sources/pugixml-$(version).tar.gz")
    add_versions("1.15", "b39647064d9e28297a34278bfb897092bf33b7c487906ddfc094c9e8868bddcb")
    add_deps("cmake")
    add_configs("wchar", {default = false, type = "boolean"})
    add_configs("exceptions", {default = true, type = "boolean"})
    add_configs("headeronly", {default = false, type = "boolean"})
    on_install(function (package)
        import("package.tools.cmake").install(package, {"-DBUILD_SHARED_LIBS=OFF", "-DPUGIXML_BUILD_TESTS=OFF"})
    end)
